// CONCOURS MAROC FINAL | Seule cette node doit être éditée après import.
// API Keys ne vont JAMAIS ici. Buffer = DRAFT SEULEMENT.
const cfg = {
  maxLiensListe: 36,
  maxAppelsIA: 2,          // coût limité pour le premier test
  daysBack: 45,
  requirePDF: true,
  instagramChannelId: 'REPLACE_WITH_IG_CHANNEL_ID',
  tiktokChannelId: 'REPLACE_WITH_TT_CHANNEL_ID',
  includeInstagram: true,
  includeTikTok: false,   // passer à true SEULEMENT quand Instagram est validé
  allowBufferDrafts: false,          // passer à true pour autoriser les DRAFTS
  allowManualBufferDrafts: false,    // passer à true pour test Execute Workflow manuel
};
return [{json:cfg}];

const html=String($input.first().json.data??$input.first().json.body??'');
if(!html.includes('/concours/details/'))throw new Error('HTML de liste inattendu, aucun concours trouvé.');
const cfg=$('01 CONFIG - Editions minimales').first().json;
const dec=s=>String(s).replace(/&amp;/gi,'&').replace(/&nbsp;|&#160;/gi,' ').replace(/&#39;|&apos;|&rsquo;/gi,"'").replace(/&quot;/gi,'"');
const strip=s=>dec(String(s).replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ')).trim();
const seen=new Set(),out=[];
for(const m of html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)){
 const href=dec(m[1]);
 const id=href.match(/\/fr\/concours\/details\/([0-9a-f-]{30,})/i);
 if(!id)continue;
 const url='https://www.emploi-public.ma/fr/concours/details/'+id[1].toLowerCase();
 const title=strip(m[2]);
 if(!/Annonce|Avis de concours de recrutement/i.test(title))continue;
 if(/annul[eé]|résultat|resultat|convocation/i.test(title))continue;
 if(seen.has(url))continue;
 seen.add(url);out.push({json:{source_url:url,titre_liste:title.slice(0,700)}});
 if(out.length>=cfg.maxLiensListe)break;
}
if(!out.length)throw new Error('Aucun lien détecté; HTML du portail à vérifier.');
return out;

// On lit toutes les lignes du tableau UNE SEULE FOIS.
// Instagram et TikTok sont gérés séparément : un draft IG n'empêche pas TikTok.
const cfg=$('01 CONFIG - Editions minimales').first().json;
const known=new Map();
for(const r of $input.all()) {
 const d=r.json||{};
 if (typeof d.source_url==='string'&&d.source_url) known.set(d.source_url.trim(),d);
}
const links=$('03 Extraire liens officiels').all();
const out=[];const seen=new Set();
for(const item of links){
 const p=item.json;
 if(!p.source_url||seen.has(p.source_url))continue;
 seen.add(p.source_url);
 const old=known.get(p.source_url)||{};
 const needsInstagram=!!cfg.includeInstagram&&!String(old.instagram_draft_id||'').trim();
 const needsTikTok=!!cfg.includeTikTok&&!String(old.tiktok_draft_id||'').trim();
 if(!needsInstagram&&!needsTikTok)continue;
 out.push({json:{...p,needsInstagram,needsTikTok,
    prior_instagram_draft_id:old.instagram_draft_id||null,
    prior_tiktok_draft_id:old.tiktok_draft_id||null}});
}
return out;

const meta=$('06 Choisir concours sans doublon').item.json;
const raw=String($input.item.json.data??$input.item.json.body??'');
if(raw.length<400)throw new Error('HTML fiche trop court '+meta.source_url);
const dec=s=>String(s).replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&rsquo;|&apos;|&#39;/gi,"'").replace(/&eacute;/gi,'é').replace(/&agrave;/gi,'à').replace(/&#x([0-9a-f]+);/gi,(_,x)=>String.fromCodePoint(parseInt(x,16))).replace(/&#(\d+);/g,(_,x)=>String.fromCodePoint(+x));
const content=dec(raw.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ')).trim();
let idx=content.search(/Détail de l.annonce/i), end=content.search(/Concours similaires/i);
const txt=idx>=0?content.slice(idx,end>idx?end:idx+8500):content.slice(0,8500);
function field(start,stops,max=1600){const m=txt.match(start);if(!m)return '';let t=txt.slice(m.index+m[0].length,m.index+m[0].length+max);const x=stops.map(r=>t.search(r)).filter(x=>x>=0);if(x.length)t=t.slice(0,Math.min(...x));return t.replace(/^[\s\-:–—]+/,'').trim();}
const org=field(/Administration qui recrute\s*:?\s*/i,[/Délai de dépôt des candidatures/i],500);
const lim=field(/Délai de dépôt des candidatures\s*:?\s*/i,[/Date du concours/i,/Date de publication/i],180);
const concours=field(/Date du concours\s*:?\s*/i,[/Date de publication/i,/Téléchargement/i],180);
const publication=field(/Date de publication\s*:?\s*/i,[/Téléchargement/i,/Description/i],180);
const grade=field(/Grade\s*:\s*/i,[/Nombre de postes/i,/Type de recrutement/i],330);
const spec=field(/Spécialité\s*:\s*/i,[/Grade\s*:/i,/Nombre de postes/i],900);
const nb=Number(field(/Nombre de postes\s*:\s*/i,[/Type de recrutement/i,/Type de dépôt/i],90).match(/\d+/)?.[0]??0);
const code=field(/Code du concours\s*:\s*/i,[/Administration organisatrice/i,/Contacter l'administration/i],85);
const depot=field(/Site de dépôt\s*:\s*/i,[/Informations supplémentaires/i,/Code du concours/i],300).match(/https?:\/\/[^\s<>]+/)?.[0]||null;
const mm={janvier:1,fevrier:2,mars:3,avril:4,mai:5,juin:6,juillet:7,aout:8,septembre:9,octobre:10,novembre:11,decembre:12};
function iso(v){const s=String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let m=s.match(/(\d{1,2})[/-](\d{1,2})[/-](20\d{2})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=s.match(/(\d{1,2})\s+([a-z]+)\s+(20\d{2})/);return m&&mm[m[2]]?`${m[3]}-${String(mm[m[2]]).padStart(2,'0')}-${m[1].padStart(2,'0')}`:null;}
// Exact PDF opening decree link; do not guess using source UUID.
const hrefs=[...raw.matchAll(/href\s*=\s*["']([^"']+)["']/gi)].map(m=>dec(m[1]));
const pdfHref=hrefs.find(h=>/\/concours\/download\/arrete\/[0-9a-f-]+/i.test(h));
const path=pdfHref?.match(/\/fr\/concours\/download\/arrete\/[0-9a-f-]+/i)?.[0]||null;
const pdf_url=path?'https://www.emploi-public.ma'+path:null;
const p={source_url:meta.source_url,titre_liste:meta.titre_liste,organisme_fiche:org,grade_fiche:grade,postes_fiche:nb,specialite_fiche:spec,date_limite_fiche:iso(lim),date_limite_texte:lim,date_concours_fiche:iso(concours),date_publication:iso(publication),code_concours:code,lien_inscription_fiche:depot,pdf_url,fiche_texte:txt.slice(0,6500)};
return {json:{...meta,...p}};

const cfg=$('01 CONFIG - Editions minimales').first().json;
const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Casablanca',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const dt=Object.fromEntries(parts.map(x=>[x.type,x.value]));
const today=`${dt.year}-${dt.month}-${dt.day}`;
const out=[];
for(let i=0;i<$input.all().length;i++){
 const p=$input.all()[i].json;
 if(!p.date_limite_fiche||p.date_limite_fiche<today)continue;
 if(!p.date_publication)continue;
 const age=(Date.parse(today+'T12:00:00Z')-Date.parse(p.date_publication+'T12:00:00Z'))/86400000;
 if(age<0||age>cfg.daysBack)continue;
 if(!p.organisme_fiche||!p.grade_fiche||p.postes_fiche<1)continue;
 out.push({json:{...p,eligibilite:'EN_ATTENTE_IA'},pairedItem:{item:i}});
 if(out.length>=cfg.maxAppelsIA)break;
}
return out;

const p=$input.item.json;
const system=`Tu es un vérificateur expert des concours officiels marocains. Tu analyses UNE FICHE emploi-public.ma ET SON ARRETE PDF partagé. Le PDF peut être un scan: lis les pages visuellement. Retourne uniquement un objet JSON valide sans Markdown. Champs: organisme (string|null), grade (string|null), nombre_postes (entier|null), diplomes (string[]), specialites (string[]), conditions (string[]), documents (string[]), date_limite (YYYY-MM-DD|null), date_concours (YYYY-MM-DD|null), lien_inscription (string|null), note_divergence (string|null), statut_verification ('extrait'|'a_verifier'). IMPORTANT: nombre_postes et specialites doivent correspondre UNIQUEMENT à la fiche individuelle, jamais au total d'un PDF partagé. Le PDF sert aux conditions, diplômes et vérifications. La DATE LIMITE de candidature vient de la fiche. "avant le 18/10" peut signifier 17/10 comme dernier jour et n'est pas automatiquement une contradiction. Ne confonds pas doctorat obtenu à l'étranger et nationalité étrangère. Ne déduis pas de diplôme par le grade. Quand données non prouvées, laisser vide/null, et statut a_verifier. Ne rends PAS de faux renseignements.`;
const description=JSON.stringify({source_url:p.source_url,fiche:{organisme:p.organisme_fiche,grade:p.grade_fiche,nombre_postes:p.postes_fiche,specialite:p.specialite_fiche,date_limite:p.date_limite_fiche,date_concours:p.date_concours_fiche,lien_inscription:p.lien_inscription_fiche,texte:p.fiche_texte}});
const body={model:'gpt-4.1-mini',input:[{role:'system',content:[{type:'input_text',text:system}]},{role:'user',content:[{type:'input_text',text:'FICHE INDIVIDUELLE: '+description},{type:'input_file',file_url:p.pdf_url}]}],text:{format:{type:'json_object'}},max_output_tokens:2200};
return {json:{...p,openai_body:body}};

// Concours Maroc V3.3 — Node 10 : verification prudente fiche/PDF.
// Mode n8n : Run Once for Each Item.
const p = $('11 Préparer OpenAI (PDF & Fiche)').item.json;
const r = $input.item.json;
const t = r.output?.flatMap(x => x.content || []).find(x => x.type === 'output_text')?.text || '';
const errors = [];
const warnings = [];
let ai = {};
try {
  if (!t) throw new Error(r.error?.message || r.message || 'OpenAI sans réponse');
  ai = JSON.parse(t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
} catch (e) {
  errors.push('OPENAI_ERROR: ' + String(e.message).slice(0, 180));
}
const arr = x => Array.isArray(x) ? x.map(v => String(v ?? '').trim()).filter(Boolean) : [];
const norm = x => String(x ?? '').toLowerCase().normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').replace(/[\u064b-\u065f]/g, '')
  .replace(/[^a-z0-9\u0600-\u06ff]+/g, ' ').trim();
const originalSpec = String(p.specialite_fiche || '').trim();
const isPlaceholder = !originalSpec || /(?:^|\s)(?:voir|consulter|annonce|reporter|انظر|راجع|الاعلان)(?:\s|$)/i.test(norm(originalSpec));
const pdfSpecs = arr(ai.specialites);
const ficheSpecs = originalSpec.split(/\s+-\s+/).map(x => x.trim()).filter(Boolean);
const category = s => {
  const x = norm(s);
  if (/plomb|ترصيص|سباك/.test(x)) return 'plomberie';
  if (/mecan|voiture|automobile|carrosserie|ميكانيك|مصلح مركبات|سيارات/.test(x)) return 'mecanique-auto';
  return x;
};

if (!p.pdf_url) errors.push('PDF ABSENT');
if (!p.date_limite_fiche) errors.push('DATE FICHE ABSENTE');
if (!p.grade_fiche || !p.organisme_fiche) errors.push('GRADE/ORGANISME FICHE ABSENT');
if (!Number.isInteger(p.postes_fiche) || p.postes_fiche < 1) errors.push('POSTES FICHE ABSENTS');
if (!Number.isInteger(ai.nombre_postes) || ai.nombre_postes !== p.postes_fiche) errors.push('POSTES IA != FICHE');
if (ai.grade && p.grade_fiche && norm(ai.grade) !== norm(p.grade_fiche)) {
  errors.push('GRADE IA != FICHE');
}
if (!pdfSpecs.length) errors.push('SPECIALITES NON EXTRAITES DU PDF');
if (isPlaceholder) {
  warnings.push('La fiche ne détaille pas les spécialités : utiliser celles du PDF officiel après contrôle.');
} else if (pdfSpecs.length) {
  const ficheSet = [...new Set(ficheSpecs.map(category))];
  const pdfSet = [...new Set(pdfSpecs.map(category))];
  if (!ficheSet.every(s => pdfSet.includes(s)) || !pdfSet.every(s => ficheSet.includes(s))) {
    errors.push('SPECIALITES FICHE / PDF A RECONCILIER');
  }
  if (ficheSpecs.length > Number(p.postes_fiche || 0) && ficheSpecs.length > 1) {
    errors.push('FICHE : ' + ficheSpecs.length + ' MENTIONS DE SPECIALITE POUR ' + p.postes_fiche + ' POSTES');
  }
}
const dipl = arr(ai.diplomes);
if (!dipl.length) errors.push('DIPLOMES NON EXTRAITS');
if (!ai.date_limite || ai.date_limite !== p.date_limite_fiche) errors.push('DATE IA != FICHE');
if (ai.statut_verification !== 'extrait') errors.push('IA DEMANDE REVISION');

const note = String(ai.note_divergence || '').trim();
if (note) {
  // Simple précision sur une plage d'inscription : pas un conflit de date.
  const dateOnly = /date|p[eé]riode|candidature|d[eé]p[oô]t|octobre|novembre|jusqu|avant/i.test(note)
    && !/sp[eé]cialit|grade|poste|dipl[oô]me|âge|age|nationalit|discordance sur/i.test(note);
  if (dateOnly && ai.date_limite === p.date_limite_fiche) {
    warnings.push('Note sur la période de candidature : ' + note.slice(0, 210));
  } else {
    errors.push('DIVERGENCE DOCUMENTAIRE: ' + note.slice(0, 180));
  }
}

// Ne pas recopier des âges maximaux différents comme s'ils s'appliquaient à tous.
const rawConditions = arr(ai.conditions);
const maxAges = [...new Set(rawConditions.flatMap(s => [
  ...[...s.matchAll(/(\d{2})\s*(?:سنة|سنوات|ans?)\s*(?:على الأكثر|كحد أقصى|maximum|au plus)/gi)].map(m => Number(m[1])),
  ...[...s.matchAll(/(?:لا يتجاوز|لا تتجاوز|دون أن تتجاوز|ne dépasse pas|sans dépasser)\s*(\d{2})\s*(?:سنة|سنوات|ans?)/gi)].map(m => Number(m[1]))
]))];
const exceptionAgeExpliquee = rawConditions.some(s => /يمكن تمديد|dérogation|prolongation|à titre exceptionnel|بصفة استثنائية/i.test(s));
const ageAmbigu = maxAges.length > 1 && !exceptionAgeExpliquee;
if (ageAmbigu) warnings.push('LIMITES AGE MULTIPLES (' + maxAges.join('/') + ') : préciser les catégories avant publication.');
const conditions = ageAmbigu
  ? rawConditions.filter(s => !/(?:\d{2}\s*(?:سنة|سنوات|ans?)|العمر|age|âge)/i.test(s))
      .concat(['شروط السن تختلف حسب فئة المترشح؛ يرجى الرجوع للإعلان الرسمي.'])
  : rawConditions;

const status = errors.length ? 'A_VERIFIER' : 'COHERENT';
return {json: {
  source_url: p.source_url,
  pdf_url: p.pdf_url,
  organisme: p.organisme_fiche,
  grade: p.grade_fiche,
  postes: p.postes_fiche,
  specialites: isPlaceholder ? pdfSpecs : ficheSpecs,
  diplomes: dipl,
  conditions,
  documents: arr(ai.documents),
  date_limite: p.date_limite_fiche,
  date_limite_texte: p.date_limite_texte,
  date_concours: p.date_concours_fiche,
  date_publication: p.date_publication,
  code_concours: p.code_concours,
  lien_inscription: ai.lien_inscription || p.lien_inscription_fiche,
  ai_extraction: ai,
  verification_automatique: status,
  erreurs_verification: errors,
  avertissements_verification: warnings,
  revue_humaine_recommandee: warnings.length > 0 || errors.length > 0,
  autoriser_publication: false,
  needsInstagram: !!p.needsInstagram,
  needsTikTok: !!p.needsTikTok
}};

// Concours Maroc | Affiche fixe 1080x1350, aucun chevauchement footer.
// Informations longues : pas de points de suspension ; détails complets dans caption.
const p=$input.item.json;
if(p.verification_automatique!=='COHERENT')throw new Error('Controle non valide');
const arr=v=>Array.isArray(v)?v.map(x=>String(x??'').trim()).filter(Boolean):v?[String(v)]:[];
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const org=String(p.organisme||'');
const grade=String(p.grade||'');
const dipl=arr(p.diplomes);const specs=arr(p.specialites);const conditions=arr(p.conditions);
const date=/^\d{4}-\d\d-\d\d$/.test(p.date_limite||'')?p.date_limite.split('-').reverse().join('/'):String(p.date_limite||'Voir annonce');
const dConc=/^\d{4}-\d\d-\d\d$/.test(p.date_concours||'')?p.date_concours.split('-').reverse().join('/'):'';
const logo='https://raw.githubusercontent.com/mohammed-derouich/mohammed-derouich/main/assets/concours-maroc-logo.svg';
const showOr=(s,max,alternative)=>s.length<=max?s:alternative;
const specFull=specs.join(' · ');
const diplomaFull=dipl[0]||'Consultez l’annonce officielle';
// On privilégie l'information lisible plutôt que la coupure de texte.
const diplomaShow=showOr(diplomaFull,190,'تفاصيل الدبلوم كاملاً في الوصف المرفق');
const specShow=showOr(specFull,220,'التخصصات كثيرة، لائحة كاملة في الوصف المرفق');
const extraDipl=dipl.slice(1,3).join(' • ');
const equivShow=showOr(extraDipl||'يرجى الرجوع للإعلان الرسمي',165,'تفاصيل الدبلومات المعادلة في الوصف');
const fsOrg=org.length>85?26:org.length>58?30:36;
const fsSpec=specShow.length>155?20:specShow.length>90?24:30;
const fsDipl=diplomaShow.length>155?18:diplomaShow.length>110?21:diplomaShow.length>65?24:29;
const caption=[
  `🇲🇦 مباراة توظيف - ${org}`,
  `📋 الدرجة: ${grade}`,
  `👥 عدد المناصب: ${p.postes}`,
  `📚 التخصصات: ${specFull||'انظر الإعلان الرسمي'}`,
  `🎓 الدبلومات: ${dipl.join(' / ')||'انظر الإعلان الرسمي'}`,
  '', '📌 الشروط:',...conditions.slice(0,6).map(x=>'• '+x),
  '',`⏰ آخر أجل: ${date}`,
  dConc?`🗓️ تاريخ المباراة: ${dConc}`:'',
  p.lien_inscription?`📝 التسجيل: ${p.lien_inscription}`:'',
  `🔗 الإعلان الرسمي: ${p.source_url}`,
  '',...(arr(p.avertissements_verification).length?['⚠️ راجع الإعلان الرسمي للتأكد من الشروط والتفاصيل.']:[]),
  'صفحة إخبارية مستقلة وغير حكومية، ليست جهة توظيف رسمية.',
  '#ConcoursMaroc #مباريات_التوظيف #الوظيفة_العمومية'
].filter(x=>x!==null&&x!==undefined).join('\n');
